package com.sktpj.gbmoder;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

/** Embedded handheld chassis images supplied for GBModer's console backgrounds. */
final class ChassisImageAssets {
    private static final String GB = "";
    private static final String GBC = "";
    private static final String GBA = "";
    private static final String DS = "";

    private static Bitmap gbBitmap;
    private static Bitmap gbcBitmap;
    private static Bitmap gbaBitmap;
    private static Bitmap dsBitmap;

    private ChassisImageAssets() {}

    static synchronized Bitmap get(String mode) {
        if (GameBoyFilter.MODE_GBC.equals(mode)) {
            if (gbcBitmap == null) gbcBitmap = decode(GBC);
            return gbcBitmap;
        }
        if (GameBoyFilter.MODE_GBA.equals(mode)) {
            if (gbaBitmap == null) gbaBitmap = decode(GBA);
            return gbaBitmap;
        }
        if (GameBoyFilter.MODE_DS.equals(mode)) {
            if (dsBitmap == null) dsBitmap = decode(DS);
            return dsBitmap;
        }
        if (gbBitmap == null) gbBitmap = decode(GB);
        return gbBitmap;
    }

    private static Bitmap decode(String encoded) {
        byte[] bytes = Base64.decode(encoded, Base64.DEFAULT);
        Bitmap bitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
        if (bitmap == null) throw new IllegalStateException("chassis image decode failed");
        return bitmap;
    }
}
